+/** Options for inlining a stylesheet into an HTML document. */
+export interface InlineHtmlOptions {
+  /** CSS rules to retain in a style element for pseudo-classes and media queries. */
+  preserveFallbacks?: boolean;
+}
+
+/** Inline the supplied stylesheet into matching HTML elements. */
+export function inlineHtml(
+  html: string,
+  css: string,
+  options: InlineHtmlOptions = {},
+): string {
+  const { preserveFallbacks = true } = options;
+  return juice.inlineContent(html, css, {
+    preserveMediaQueries: preserveFallbacks,
+    preservePseudos: preserveFallbacks,
+    removeStyleTags: false,
